  "targets": {
    "glasses_marco": [
      {"days": "both", "from": 0, "to": 24, "at": "nightstand_b1", "chance": "usually"},
      {"days": "weekday", "from": 6, "to": 10, "at": "desk_b1", "chance": "sometimes"}
    ]
